import assert from 'node:assert/strict';
import {readFile,writeFile,mkdir} from 'node:fs/promises';
import path from 'node:path';
import {withoutRedirectCopies} from '../../engine/redirect-pages.mjs';
import {exportRedirects} from '../../scripts/redirect-export.mjs';
const root=path.resolve(process.argv[2]||'work/redir');
const artifact=path.resolve(process.argv[3]||'artifacts/platform/redirection-installed');
const model=JSON.parse(await readFile(path.join(artifact,'captured-model.json')));
const filtered=withoutRedirectCopies(model),output=path.join(artifact,'redirect-host-check');
assert.equal(model.pages.length-filtered.pages.length,4);
await mkdir(output,{recursive:true});
const report=await exportRedirects({source:model.source,routes:filtered.pages,observed:model.observedRedirects,imported:JSON.parse(await readFile(path.join(root,'redirects-export.json'))),output});
assert.equal(report.rules.length,5);
assert.equal(report.rules.filter(r=>r.cloudflare==='http-rule').length,5);
assert.equal(report.rules.filter(r=>r.static==='html-fallback').length,3);
assert.equal(report.issues.filter(i=>i.reason==='existing-or-reserved-route').length,0);
for(const reason of ['disabled-rule','query-matching-requires-server-rule','regex-case-or-trailing-match-not-supported','group-status-conflicts-with-enabled-rule'])assert.ok(report.issues.some(i=>i.reason===reason),reason);
const rules=await readFile(path.join(output,'_redirects'),'utf8');
for(const line of ['/old-about/ /about/ 301','/temporary/ /services/ 302','/chain/ /old-about/ 307','/method/ /contact/ 308'])assert.ok(rules.includes(line));
await writeFile(path.join(artifact,'installed-redirect-check.json'),JSON.stringify({captured:model.pages.length,authored:filtered.pages.length,report},null,2));
console.log(JSON.stringify({captured:model.pages.length,authored:filtered.pages.length,httpRules:report.rules.length,staticFallbacks:3}));
